import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const x=JSON.parse('{"title":"国贸商城观景台","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/guomao-viewing-deck.md","filePath":"landmarks/guomao-viewing-deck.md","lastUpdated":1787037124000}'),n={name:"landmarks/guomao-viewing-deck.md"};function o(d,t,i,s,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="国贸商城观景台" tabindex="-1">国贸商城观景台 <a class="header-anchor" href="#国贸商城观景台" aria-label="Permalink to &quot;国贸商城观景台&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1611416457332-946853cc75d6?w=1200" alt="国贸商城观景台"></p><blockquote><p>&quot;免费俯瞰央视大楼与CBD的隐藏阳台。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>国贸商城观景台位于北京国贸商城北区6层的露天平台，是俯瞰北京CBD全景的免费观景地。站在平台上，可以近距离欣赏中央电视台总部大楼（&quot;大裤衩&quot;）、中信大厦（&quot;中国尊&quot;）以及国贸CBD鳞次栉比的摩天楼群，入夜后城市灯光亮起，车流如织、霓虹闪烁，是北京中心城区最经典的都市夜景机位之一。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">与国贸商城营业时间一致（10:00-22:00）</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">免费，无需预约</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">1-2小时</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">四季皆宜，夜晚景观最佳</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁1/10号线国贸站E2口</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市朝阳区建国门外大街1号国贸商城北区6层</td></tr></tbody></table><h2 id="观景特色" tabindex="-1">观景特色 <a class="header-anchor" href="#观景特色" aria-label="Permalink to &quot;观景特色&quot;">​</a></h2><h3 id="俯瞰央视大楼" tabindex="-1">俯瞰央视大楼 <a class="header-anchor" href="#俯瞰央视大楼" aria-label="Permalink to &quot;俯瞰央视大楼&quot;">​</a></h3><p>观景台正对中央电视台总部大楼，是拍摄&quot;大裤衩&quot;的最佳免费机位之一，白天钢结构轮廓清晰，夜晚灯光亮起后更具视觉冲击力。</p><h3 id="中国尊与cbd天际线" tabindex="-1">中国尊与CBD天际线 <a class="header-anchor" href="#中国尊与cbd天际线" aria-label="Permalink to &quot;中国尊与CBD天际线&quot;">​</a></h3><p>平台视野开阔，可同时收入中国尊、国贸三期等超高层建筑，向东望去整个CBD天际线尽收眼底。</p><h3 id="都市夜景" tabindex="-1">都市夜景 <a class="header-anchor" href="#都市夜景" aria-label="Permalink to &quot;都市夜景&quot;">​</a></h3><p>入夜后国贸桥车流灯光如长河般流动，配合周边写字楼的窗灯与霓虹，构成北京最具代表性的现代都市夜景。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>夜景路线</strong>：</p><p>国贸站E2口 → 国贸商城北区 → 一楼Nike对面电梯直达6层 → 观景台拍照 → 国贸商城晚餐</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>交通</strong>：地铁1/10号线国贸站E2口或F口出站，进入国贸商城</li><li><strong>上楼</strong>：从一楼Nike专卖店对面的电梯上6层，即可到达露天观景台</li><li><strong>错峰</strong>：观景台人气高，玻璃护栏较高，想避开人流建议傍晚蓝调时刻前到达</li><li><strong>拍摄</strong>：日落前后到夜幕降临的蓝调时刻最出片，大厦熄灯后景色会打折扣</li><li><strong>搭配</strong>：与国贸商城餐饮、三里屯、蓝色港湾等商圈串联游玩</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">1/10号线国贸站E2口或F口</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">大北窑西站、国贸站等多路公交</td></tr><tr><td style="text-align:left;"><strong>自驾</strong></td><td style="text-align:left;">定位&quot;国贸商城&quot;，有配套停车场</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">国贸商城</td><td style="text-align:center;">楼下</td><td style="text-align:left;">高端购物餐饮</td></tr><tr><td style="text-align:left;">北京合生汇</td><td style="text-align:center;">车程10分钟</td><td style="text-align:left;">美食购物中心</td></tr><tr><td style="text-align:left;">三里屯太古里</td><td style="text-align:center;">车程15分钟</td><td style="text-align:left;">潮流时尚街区</td></tr><tr><td style="text-align:left;">蓝色港湾</td><td style="text-align:center;">车程20分钟</td><td style="text-align:left;">湖畔欧式街区</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>国贸商城观景台是北京CBD夜间公共空间向市民开放的范例，让普通人无需消费即可在高处感受城市天际线的壮阔，也成为摄影爱好者与游客了解现代北京的重要窗口。</p><hr><p><strong>📍 地址</strong>：北京市朝阳区建国门外大街1号国贸商城北区6层 <strong>🚇 地铁</strong>：1/10号线国贸站E2口</p><p><strong>💡 Tips</strong>：傍晚蓝调时刻到达，观景免费，拍照出片后再去楼下用餐。</p>',29)])])}const f=e(n,[["render",o]]);export{x as __pageData,f as default};
